import type { Infer } from "convex/values";
import { vEncrypted } from "../schema";

export type Encrypted = Infer<typeof vEncrypted>;

const enc = new TextEncoder();
const dec = new TextDecoder();

function toB64(bytes: Uint8Array): string {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s);
}

function fromB64(s: string): Uint8Array<ArrayBuffer> {
  const bin = atob(s);
  const out = new Uint8Array(new ArrayBuffer(bin.length));
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function masterKey(): Promise<CryptoKey> {
  const raw = process.env.ENCRYPTION_MASTER_KEY;
  if (!raw) throw new Error("ENCRYPTION_MASTER_KEY is not set");
  return crypto.subtle.importKey("raw", fromB64(raw), "HKDF", false, [
    "deriveKey",
  ]);
}

// One AES-GCM key per (event, key version), derived from the master key, so
// no per-event key is ever stored. Bump `events.keyVersion` to rotate.
async function eventKey(eventId: string, version: number): Promise<CryptoKey> {
  return crypto.subtle.deriveKey(
    {
      name: "HKDF",
      hash: "SHA-256",
      salt: enc.encode("storytime/event"),
      info: enc.encode(`${eventId}:${version}`),
    },
    await masterKey(),
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );
}

export async function encryptText(
  eventId: string,
  version: number,
  plaintext: string,
): Promise<Encrypted> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv },
    await eventKey(eventId, version),
    enc.encode(plaintext),
  );
  return { iv: toB64(iv), ct: toB64(new Uint8Array(ct)), v: version };
}

export async function decryptText(
  eventId: string,
  value: Encrypted,
): Promise<string> {
  const pt = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: fromB64(value.iv) },
    await eventKey(eventId, value.v),
    fromB64(value.ct),
  );
  return dec.decode(pt);
}

// Keyed hash so equal places group together without storing the place.
export async function placeKeyFor(
  eventId: string,
  version: number,
  place: string,
): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    await crypto.subtle.exportKey("raw", await rawHmacKey(eventId, version)),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const sig = await crypto.subtle.sign(
    "HMAC",
    key,
    enc.encode(place.trim().toLowerCase()),
  );
  return toB64(new Uint8Array(sig)).slice(0, 22);
}

async function rawHmacKey(eventId: string, version: number): Promise<CryptoKey> {
  return crypto.subtle.deriveKey(
    {
      name: "HKDF",
      hash: "SHA-256",
      salt: enc.encode("storytime/place"),
      info: enc.encode(`${eventId}:${version}`),
    },
    await masterKey(),
    { name: "HMAC", hash: "SHA-256", length: 256 },
    true,
    ["sign"],
  );
}
EOF
cat > convex/lib/access.ts <<'EOF'
import type { Doc, Id } from "../_generated/dataModel";
import type { MutationCtx, QueryCtx } from "../_generated/server";

type Ctx = QueryCtx | MutationCtx;
export type EventRole = "owner" | "contributor" | "viewer";

const RANK: Record<EventRole, number> = { viewer: 0, contributor: 1, owner: 2 };

export async function getUserId(ctx: Ctx): Promise<Id<"users"> | null> {
  const identity = await ctx.auth.getUserIdentity();
  if (identity === null) return null;
  return ctx.db.normalizeId("users", identity.subject);
}

export async function requireUserId(ctx: Ctx): Promise<Id<"users">> {
  const userId = await getUserId(ctx);
  if (userId === null) throw new Error("Not signed in");
  return userId;
}

// Role of the signed-in user on an event, or null when they have no active
// share grant. A revoked session grants nothing.
export async function getEventAccess(
  ctx: Ctx,
  eventId: Id<"events">,
): Promise<{
  userId: Id<"users">;
  event: Doc<"events">;
  role: EventRole;
} | null> {
  const userId = await getUserId(ctx);
  if (userId === null) return null;
  const event = await ctx.db.get("events", eventId);
  if (event === null) return null;
  if (event.ownerId === userId) return { userId, event, role: "owner" };
  const session = await ctx.db
    .query("sessions")
    .withIndex("by_event_and_user", (q) =>
      q.eq("eventId", eventId).eq("userId", userId),
    )
    .unique();
  if (session === null || session.revokedAt !== undefined) return null;
  return { userId, event, role: session.role };
}

export async function requireEventAccess(
  ctx: Ctx,
  eventId: Id<"events">,
  min: EventRole,
) {
  const access = await getEventAccess(ctx, eventId);
  // Same error for "missing" and "forbidden" so ids can't be probed.
  if (access === null || RANK[access.role] < RANK[min]) {
    throw new Error("Event not found");
  }
  return access;
}
EOF
