  handler: async (ctx, args) => {
    const invite = await ctx.db
      .query("invites")
      .withIndex("by_tokenHash", (q) =>
        q.eq("tokenHash", await sha256Hex(args.token)),
      )
      .unique();
    if (invite === null) return null;
    await ctx.db.delete("invites", invite._id);
    if (invite.expiresAt < Date.now()) return null;
    return {
      eventId: invite.eventId,
      invitedBy: invite.invitedBy,
      role: invite.role,
    };
  },
});

// "This isn't important anymore": hard delete, no tombstone.
export const dismiss = mutation({
  args: { inviteId: v.id("invites"), eventId: v.string() },
  returns: v.boolean(),
  handler: async (ctx, args) => {
    const invite = await ctx.db.get("invites", args.inviteId);
    if (invite === null || invite.eventId !== args.eventId) return false;
    await ctx.db.delete("invites", args.inviteId);
    return true;
  },
});

export const listForEvent = query({
  args: { eventId: v.string() },
  returns: v.array(
    v.object({
      inviteId: v.id("invites"),
      role: vRole,
      expiresAt: v.number(),
    }),
  ),
  handler: async (ctx, args) => {
    const rows = await ctx.db
      .query("invites")
      .withIndex("by_event", (q) => q.eq("eventId", args.eventId))
      .take(100);
    return rows
      .filter((r) => r.expiresAt >= Date.now())
      .map((r) => ({ inviteId: r._id, role: r.role, expiresAt: r.expiresAt }));
  },
});

export const purge = internalMutation({
  args: { inviteId: v.id("invites") },
  returns: v.null(),
  handler: async (ctx, args) => {
    const invite = await ctx.db.get("invites", args.inviteId);
    if (invite !== null) await ctx.db.delete("invites", args.inviteId);
    return null;
  },
});

// Backstop for the per-invite timers; called from the app's daily cron.
export const sweep = mutation({
  args: {},
  returns: v.number(),
  handler: async (ctx) => {
    const expired = await ctx.db
      .query("invites")
      .withIndex("by_expiresAt", (q) => q.lt("expiresAt", Date.now()))
      .take(100);
    for (const invite of expired) await ctx.db.delete("invites", invite._id);
    return expired.length;
  },
});
