@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground font-sans antialiased;
  }
}

/*
 * Magnetic hover (after jhey's bento effect). The hovered item claims the
 * `--magnet` anchor and a single indicator slides to its edges.
 *   - Firefox can't animate anchor insets yet, so it gets the instant jump.
 *   - Browsers without anchor positioning keep each item's own hover style.
 *   - Touch devices have no hover, so the indicator is never shown.
 */
.magnetic {
  position: relative;
}
.magnetic-indicator {
  display: none;
}
@supports (anchor-name: --magnet) {
  @media (hover: hover) {
    .magnetic > * {
      position: relative;
      z-index: 1;
    }
    .magnetic > *:hover {
      anchor-name: --magnet;
    }
    .magnetic-indicator {
      display: block;
      position: absolute;
      z-index: 0;
      position-anchor: --magnet;
      inset: anchor(inside);
      border-radius: var(--radius-lg);
      background: var(--accent);
      pointer-events: none;
      opacity: 0;
      transition:
        inset 0.28s cubic-bezier(0.2, 0.9, 0.3, 1.1),
        opacity 0.2s ease;
    }
    .magnetic:has(> *:hover) > .magnetic-indicator {
      opacity: 1;
    }
    /* the indicator draws the hover, so drop the items' own */
    .magnetic > *:hover {
      background-color: transparent;
    }
  }
}
@media (prefers-reduced-motion: reduce) {
  .magnetic-indicator {
    transition: none;
  }
}
