      <ConvexAuthProvider client={convex} api={api.auth}>
        {children}
      </ConvexAuthProvider>
    ),
  });
}

declare module "@tanstack/react-router" {
  interface Register {
    router: ReturnType<typeof getRouter>;
  }
}
